  "embedding": {
    "defaultModelID": "Qwen/Qwen3-Embedding-0.6B",
    "fallbackModelID": "current-baseline-embedding-model",
    "teacherModelID": "Qwen/Qwen3-Embedding-4B",
    "provider": "local",","language":"markdown","lineEnd":65,"lineStart":1,"module":"docs","path":"docs/APP_PLAN.md","sourceHash":"7386a0928f4f25dac0d91eea19671db3ace032af9a41d394c3f969e677d1566d"}

