            guard sourceCounts[r.source.id, default: 0] < primaryChunksPerSource else { continue }","language":"swift","lineEnd":66,"lineStart":1,"module":"RAG","path":"ios/Lumen/RAG/RAGContextBuilder.swift","sourceHash":"3568c6fe5b583c95edd33441871b859918a824a6d08ae2b65fbadd0aa120aa1e"}

